   for(let current=absolute;current!==base;current=path.dirname(current)){
    assert(current.startsWith(base+path.sep));if(native.existsSync(current)){const stat=native.lstatSync(current);assert(!stat.isSymbolicLink());assert.equal(native.realpathSync(current),current);if(stat.isFile())assert.equal(stat.nlink,1);else assert(stat.isDirectory());}
   }
