 for(const [name,value]of Object.entries(native))if(typeof value==='function')effect.patch(fs,name,effect.deny('unsupported proxy filesystem:'+name));
 for(const [name,value]of Object.entries(fs.promises))if(typeof value==='function')effect.patch(fs.promises,name,effect.deny('async proxy filesystem:'+name));
 for(const name of ['existsSync','lstatSync','statSync','realpathSync','readdirSync'])effect.patch(fs,name,(file,...args)=>{owned(file,true);return native[name](file,...args);});
 effect.patch(fs,'openSync',(file,flags,...args)=>{const read=flags==='r'||flags===native.constants.O_RDONLY||flags===(native.constants.O_RDONLY|(native.constants.O_NOFOLLOW??0));owned(file,read);const fd=native.openSync(file,flags,...args);descriptors.set(fd,file);return fd;});
