function distributionCopyClosure(payload) {
    const recipe=join(payload,"Dockerfile.distribution");
    assert.equal(realpathSync(payload),payload,"actual payload root must be canonical");
    const owned=selected=>{
        const file=resolve(selected);
        const offset=relative(payload,file);
        assert.ok(offset && offset!==".." && !offset.startsWith(`..${sep}`),"distribution input cannot escape payload");
        assert.equal(realpathSync(file),file,"distribution input cannot resolve through an alias");
        for(let selected=file;selected!==payload;selected=dirname(selected))assert.equal(lstatSync(selected).isSymbolicLink(),false,"distribution input must not traverse symlink");
        return file;
    };
    const lines=readFileSync(owned(recipe),"utf8").replace(/\\\r?\n/g," ").split(/\r?\n/);
    const local=[],stages=[],availableStages=new Set();
    for(const raw of lines){
        const line=raw.trim();
        const from=/^FROM\s+\S+\s+AS\s+(\S+)$/i.exec(line);if(from)availableStages.add(from[1]);
        if(!/^COPY\s/i.test(line))continue;
        let body=line.replace(/^COPY\s+/i,"");const flags=[];
        while(body.startsWith("--")){const flag=/^(\S+)\s+/.exec(body);assert.ok(flag,"complete COPY flag required");flags.push(flag[1]);body=body.slice(flag[0].length);}
        const stage=flags.find(flag=>flag.startsWith("--from="));
        const fields=body.startsWith("[")?JSON.parse(body):body.split(/\s+/);
        assert.ok(fields.length>=2,"COPY has source and destination");
        if(stage){assert.ok(availableStages.has(stage.slice(7)),"COPY stage must be declared");stages.push(stage.slice(7));continue;}
        for(const source of fields.slice(0,-1)){
            assert.equal(typeof source,"string");assert.ok(!/[?*\[\]$]/.test(source),"COPY inputs must be literal payload paths");
            const pending=[owned(join(payload,source))];
            while(pending.length){const file=pending.pop(),stat=lstatSync(file);assert.ok(stat.isDirectory()||stat.isFile(),'ordinary COPY input');if(stat.isDirectory())for(const entry of readdirSync(file))pending.push(owned(join(file,entry)));else assert.equal(stat.nlink,1,'single-link COPY file');}
            local.push(source);
        }
    }
    assert.ok(local.includes("scripts/localhost-proxy/")&&local.includes("scripts/ccc-entrypoint.sh"));
    assert.ok(local.includes("dist/device-lab-mcp")&&local.includes("dist/packages"));
    for(const [source,expected]of Object.entries(PROXY_SHIPPING_NATIVE_HASHES))assert.equal(createHash("sha256").update(readFileSync(owned(join(payload,source)))).digest("hex"),expected,"retained proxy source/native asset "+source);
    return {consumer:"COPY-closure",result:"PASS",layer:"actual-payload/local-COPY/native-hashes",local,stages};
}
