const WORKSPACE_FOLLOWUP_DECLARATIONS=`
import {removeWorkspaceThenContainers,prepareWorkspaceContainerRemovalPlan,removePreparedWorkspaceContainers,withWorkspaceRemovalLifecycleLock,removeWorkspaceContainerByIdentity} from './dist/index.js';
import {createWorkspaceContentRepairAdmission} from './dist/application/workspace/content-repair-admission.js';
import {createWorkspaceCliRemoval} from './dist/application/workspace/cli-removal.js';
import type {WorkspaceContentRepairAdmissionPorts} from './dist/ports/workspace/content-repair-admission.js';
import type {WorkspaceCliRemovalPorts} from './dist/ports/workspace/cli-removal.js';
declare const repairPorts:WorkspaceContentRepairAdmissionPorts;declare const removalPorts:WorkspaceCliRemovalPorts;
const repair:Promise<void>=createWorkspaceContentRepairAdmission(repairPorts)('source','workspace','child','feature');
const remove:void=createWorkspaceCliRemoval(removalPorts)('source','feature',false);
const raw={errors:[] as string[],extra:123 as const};const receipt=removeWorkspaceThenContainers(()=>raw,()=>['container']);const exact:typeof raw=receipt.result;
const planned=prepareWorkspaceContainerRemovalPlan('workspace');const names:string[]=removePreparedWorkspaceContainers(planned);
const lock:1=withWorkspaceRemovalLifecycleLock('project',false,()=>1 as const,(_key,operation)=>operation(),()=>[]);
const removed:boolean=removeWorkspaceContainerByIdentity('name');
// @ts-expect-error Native admission composition is mandatory.
createWorkspaceContentRepairAdmission();
// @ts-expect-error Semantic removal composition is mandatory.
createWorkspaceCliRemoval();
// @ts-expect-error Selected native repair must remain synchronous.
createWorkspaceContentRepairAdmission({...repairPorts,repairConfirmed:async()=>null});
// @ts-expect-error Prompt remains asynchronous.
createWorkspaceContentRepairAdmission({...repairPorts,prompt:()=> 'yes'});
// @ts-expect-error Required native family guard cannot be omitted.
createWorkspaceCliRemoval({...removalPorts,selectFamilyLock:undefined});
// @ts-expect-error Runtime readiness does not settle asynchronously.
createWorkspaceCliRemoval({...removalPorts,selectRuntimeReadiness:()=>async()=>undefined});
// @ts-expect-error Canonical workspace result remains synchronous.
createWorkspaceCliRemoval({...removalPorts,selectRemoveWorkspace:()=>async()=>({removed:[],errors:[]})});
// @ts-expect-error Captured managed identity remains synchronous.
createWorkspaceCliRemoval({...removalPorts,selectManagedIdentity:()=>async()=>null});
// @ts-expect-error Exit must never return normally.
createWorkspaceCliRemoval({...removalPorts,selectExit:()=>()=>undefined});
void[repair,remove,exact,names,lock,removed];
`;
