import type {LabRunnerDiagnosticsPorts} from "./dist/ports/lab-runner-diagnostics.js";
declare const doctor:DoctorPorts;declare const labs:LabRunnerDiagnosticsPorts;declare const native:LabRunnerRunConfig;
const nativeFits:LabRunnerConfigObservation=native;
const doctorCheck:DoctorCheck={name:'Runtime',status:'ok',message:'ready'};const doctorRuntime:DoctorRuntimeInfo={runtime:'docker',version:null,flavor:'native'};const doctorProbe:DoctorProbeResult={status:null,stdout:null};
const doctorStatus:'ok'|'warn'|'error'=doctorCheck.status;const runtimeVersion:string|null|undefined=doctorRuntime.version;const probeStatus:number|null=doctorProbe.status;
