const healthy:boolean=runDoctor("/private");const business:boolean=createDoctor(doctor)("/private");
const snapshot:LabRunnerSnapshot=labRunnerSnapshot();const status:string=formatLabRunnerStatus(undefined);const smoke:string=formatLabRunnerSmoke();const exit:number=labsCli([]);
const published:undefined=labs.publishOutput("text");
