createDoctor({});
// @ts-expect-error Doctor publication must complete synchronously.
const asyncPublication:DoctorPorts["capturePublication"]=()=>async()=>undefined;
// @ts-expect-error Public Doctor return remains synchronous boolean.
const pending:Promise<boolean>=runDoctor("private");
// @ts-expect-error Required Labs native observations cannot be omitted.
createLabRunnerDiagnostics({});
// @ts-expect-error Labs snapshot remains synchronous.
const deferred:Promise<LabRunnerSnapshot>=labRunnerSnapshot();
